echo "# Custom Log Format Definition"
server "/etc/nginx/nginx.conf" -e "http {
    log_format benchmark_combined '$remote_addr - $remote_user [$time_local] \"$request_method $request_uri $server_port\" $status $body_bytes_sent \"$http_user_agent\"';
    # Rate Limiting Zone Definition
    limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
}" | sed -e '/^}/i\n\//// BEGIN custom log format and limit_req_zone definition\n/' /etc/nginx/nginx.conf

echo "" > /etc/nginx/conf.d/benchmark-site.conf
cat <<EOF > /etc/nginx/conf.d/benchmark-site.conf
server {
    listen 8080;
    server_name localhost;

    # Logging configuration
    access_log /var/log/nginx/benchmark-access.log benchmark_combined;
    error_log /var/log/nginx/benchmark-error.log warn;

    # Root directory and Index file
    root /var/www/html;
    index index.html;

    # Rate limiting application
    limit_req zone=benchmark_limit burst=10 nodelay;

    # Custom 404 error page
    error_page 404 /404.html =404;

    # Send files from /var/www/html
    location / { rhildir = /var/www/html; expires 1h; }
}
EOF

